def export_rows(rows: list[dict], fmt: str = "csv") -> str:
    if fmt != "csv":
        raise ValueError(f"unsupported format: {fmt}")
    lines = ["id,name"]
    for row in rows:
        lines.append(f"{row['id']},{row['name']}")
    return "\n".join(lines) + "\n"

